22	/**
23	 * 虫情处置链服务：上报、确认、虫迹登记、解除申请与双方确认解除。
24	 *
25	 * <p>写操作均通过 {@link IdempotentExecutor} 执行，事务在幂等锁内提交，
26	 * 保证并发下同键同参返回首次结果、同库区同时刻仅一条进行中处置链。
27	 */
28	@Service
29	public class PestCaseService {
30	
31	    /** 已上报（尚未确认，不拦截出库）。 */
32	    public static final String STATUS_REPORTED = "REPORTED";
33	    /** 已确认，处置中，禁止该库区出库登记。 */
34	    public static final String STATUS_CONFIRMED = "CONFIRMED";
35	    /** 已投放，进入 14 天监测期。 */
36	    public static final String STATUS_TREATED = "TREATED";
37	    /** 已申请解除，待消杀与库房双方确认。 */
38	    public static final String STATUS_RELEASE_APPLIED = "RELEASE_APPLIED";
39	    /** 已解除，库区恢复正常。 */
40	    public static final String STATUS_RELEASED = "RELEASED";
41	
42	    /** 投放后监测期天数。 */
43	    static final int MONITOR_DAYS = 14;
44	    /** 相邻库区虫情统计窗口天数。 */
45	    static final int ADJACENT_WINDOW_DAYS = 90;
46	
47	    private static final RowMapper<CaseRow> CASE_MAPPER = (rs, rowNum) -> new CaseRow(
48	            rs.getLong("id"),
49	            rs.getLong("zone_id"),
50	            rs.getString("status"),
51	            rs.getString("reporter"),
52	            rs.getString("description"),
53	            rs.getObject("reported_at", LocalDateTime.class),
54	            rs.getObject("confirmed_at", LocalDateTime.class),
55	            rs.getObject("treated_at", LocalDateTime.class),
56	            rs.getObject("release_applied_at", LocalDateTime.class),
57	            rs.getObject("disinfect_confirmed_at", LocalDateTime.class),
58	            rs.getObject("storage_confirmed_at", LocalDateTime.class),
59	            rs.getObject("released_at", LocalDateTime.class));
60	
61	    private static final RowMapper<Zone> ZONE_MAPPER = (rs, rowNum) -> new Zone(
62	            rs.getLong("id"),
63	            rs.getString("code"),
64	            rs.getString("name"),
65	            splitAdjacent(rs.getString("adjacent_codes")));
66	
67	    private final JdbcClient jdbc;
68	    private final IdempotentExecutor idempotent;
69	    private final Clock clock;
70	
71	    public PestCaseService(JdbcClient jdbc, IdempotentExecutor idempotent, Clock clock) {
72	        this.jdbc = jdbc;
73	        this.idempotent = idempotent;
74	        this.clock = clock;
75	    }
76	
77	    /**
78	     * 虫情上报：按库区登记，创建处置链并占用库区处置位；同库区已有进行中处置链时拒绝（409）。
79	     * 上报后检查相邻组团 90 日窗口，恰第 2 次虫情时触发整体预防性消杀评估。
80	     */
81	    public PestDtos.CaseResponse report(String zoneCode, PestDtos.ReportRequest request) {
82	        Map<String, Object> payload = new LinkedHashMap<>();
83	        payload.put("zoneCode", zoneCode);
84	        payload.put("reporter", request.reporter());
85	        payload.put("description", request.description());
86	        return idempotent.execute(request.requestId(), payload, PestDtos.CaseResponse.class, () -> {
87	            Zone zone = zoneByCode(zoneCode);
88	            LocalDateTime now = LocalDateTime.now(clock);
89	            KeyHolder keyHolder = new GeneratedKeyHolder();
90	            jdbc.sql("INSERT INTO pest_case (zone_id, status, reporter, description, reported_at)"
91	                            + " VALUES (?, ?, ?, ?, ?)")
92	                    .param(zone.id()).param(STATUS_REPORTED).param(request.reporter())
93	                    .param(request.description()).param(now)
94	                    .update(keyHolder, "id");
95	            long caseId = keyHolder.getKey().longValue();
96	            try {
97	                jdbc.sql("INSERT INTO zone_active_case (zone_id, case_id, created_at) VALUES (?, ?, ?)")
98	                        .param(zone.id()).param(caseId).param(now)
99	                        .update();
100	            } catch (DuplicateKeyException e) {
101	                throw ApiException.conflict("该库区已存在进行中的处置链，不允许重复上报");
102	            }
103	            triggerEvaluationIfSecond(zone, caseId, now);
104	            return new PestDtos.CaseResponse(caseId, zone.code(), STATUS_REPORTED);
105	        });
106	    }
107	
108	    /**
109	     * 确认虫情：处置链进入处置状态，此后该库区禁止出库登记。
110	     */
111	    public PestDtos.CaseResponse confirm(long caseId, PestDtos.OperatorRequest request) {
112	        Map<String, Object> payload = new LinkedHashMap<>();
113	        payload.put("caseId", caseId);
114	        payload.put("operator", request.operator());
115	        return idempotent.execute(request.requestId(), payload, PestDtos.CaseResponse.class, () -> {
116	            CaseRow row = mustFind(caseId);
117	            if (!STATUS_REPORTED.equals(row.status())) {
118	                throw ApiException.conflict("仅已上报状态的处置链可确认");
119	            }
120	            jdbc.sql("UPDATE pest_case SET status = ?, confirmed_at = ? WHERE id = ?")
121	                    .param(STATUS_CONFIRMED).param(LocalDateTime.now(clock)).param(caseId)
122	                    .update();
123	            return new PestDtos.CaseResponse(row.id(), zoneCodeOf(row.zoneId()), STATUS_CONFIRMED);
124	        });
125	    }
126	
127	    /**
128	     * 登记新增虫迹：投放后监测期内存在虫迹将阻止解除申请。
129	     */
130	    public PestDtos.TraceResponse addTrace(long caseId, PestDtos.TraceRequest request) {
131	        Map<String, Object> payload = new LinkedHashMap<>();
132	        payload.put("caseId", caseId);
133	        payload.put("description", request.description());
134	        return idempotent.execute(request.requestId(), payload, PestDtos.TraceResponse.class, () -> {
135	            CaseRow row = mustFind(caseId);
136	            if (STATUS_RELEASED.equals(row.status())) {
137	                throw ApiException.conflict("处置链已解除，不可登记虫迹");
138	            }
139	            KeyHolder keyHolder = new GeneratedKeyHolder();
140	            jdbc.sql("INSERT INTO pest_trace (case_id, description, found_at) VALUES (?, ?, ?)")
141	                    .param(caseId).param(request.description()).param(LocalDateTime.now(clock))
142	                    .update(keyHolder, "id");
143	            return new PestDtos.TraceResponse(keyHolder.getKey().longValue(), caseId);
144	        });
145	    }
