147	    /**
148	     * 申请解除：须投放后恰满 14 天且监测期内无新增虫迹。
149	     */
150	    public PestDtos.CaseResponse applyRelease(long caseId, PestDtos.OperatorRequest request) {
151	        Map<String, Object> payload = new LinkedHashMap<>();
152	        payload.put("caseId", caseId);
153	        payload.put("operator", request.operator());
154	        return idempotent.execute(request.requestId(), payload, PestDtos.CaseResponse.class, () -> {
155	            CaseRow row = mustFind(caseId);
