157	                throw ApiException.conflict("仅监测期（已投放）状态可申请解除");
158	            }
159	            LocalDateTime now = LocalDateTime.now(clock);
160	            LocalDateTime eligibleAt = row.treatedAt().plusDays(MONITOR_DAYS);
161	            if (now.isBefore(eligibleAt)) {
162	                throw ApiException.badRequest("投放后监测期未满 14 天，不得申请解除");
163	            }
164	            long traces = jdbc.sql("SELECT COUNT(*) FROM pest_trace WHERE case_id = ? AND found_at > ?")
165	                    .param(caseId).param(row.treatedAt())
166	                    .query(Long.class).single();
167	            if (traces > 0) {
168	                throw ApiException.badRequest("监测期内存在新增虫迹，不得申请解除");
169	            }
170	            jdbc.sql("UPDATE pest_case SET status = ?, release_applied_at = ? WHERE id = ?")
171	                    .param(STATUS_RELEASE_APPLIED).param(now).param(caseId)
172	                    .update();
173	            return new PestDtos.CaseResponse(row.id(), zoneCodeOf(row.zoneId()), STATUS_RELEASE_APPLIED);
174	        });
175	    }
