177	    /**
178	     * 解除确认：消杀与库房双方均确认后处置链解除，库区恢复出库。
179	     */
180	    public PestDtos.CaseResponse confirmRelease(long caseId, PestDtos.SideRequest request) {
181	        Map<String, Object> payload = new LinkedHashMap<>();
182	        payload.put("caseId", caseId);
183	        payload.put("side", request.side());
184	        return idempotent.execute(request.requestId(), payload, PestDtos.CaseResponse.class, () -> {
185	            CaseRow row = mustFind(caseId);
186	            if (!STATUS_RELEASE_APPLIED.equals(row.status())) {
187	                throw ApiException.conflict("须先申请解除后方可确认");
188	            }
189	            LocalDateTime now = LocalDateTime.now(clock);
190	            if ("DISINFECTION".equals(request.side())) {
191	                if (row.disinfectConfirmedAt() != null) {
192	                    throw ApiException.conflict("消杀方已确认，请勿重复确认");
193	                }
194	                jdbc.sql("UPDATE pest_case SET disinfect_confirmed_at = ? WHERE id = ?")
195	                        .param(now).param(caseId).update();
196	            } else if ("STORAGE".equals(request.side())) {
197	                if (row.storageConfirmedAt() != null) {
198	                    throw ApiException.conflict("库房方已确认，请勿重复确认");
199	                }
200	                jdbc.sql("UPDATE pest_case SET storage_confirmed_at = ? WHERE id = ?")
201	                        .param(now).param(caseId).update();
202	            } else {
203	                throw ApiException.badRequest("未知确认方: " + request.side());
204	            }
205	            CaseRow refreshed = mustFind(caseId);
206	            String zoneCode = zoneCodeOf(row.zoneId());
207	            if (refreshed.disinfectConfirmedAt() != null && refreshed.storageConfirmedAt() != null) {
208	                jdbc.sql("UPDATE pest_case SET status = ?, released_at = ? WHERE id = ?")
209	                        .param(STATUS_RELEASED).param(now).param(caseId).update();
210	                jdbc.sql("DELETE FROM zone_active_case WHERE zone_id = ?")
211	                        .param(row.zoneId()).update();
212	                return new PestDtos.CaseResponse(caseId, zoneCode, STATUS_RELEASED);
213	            }
214	            return new PestDtos.CaseResponse(caseId, zoneCode, STATUS_RELEASE_APPLIED);
215	        });
216	    }
