239	                row.reporter(), row.description(), row.reportedAt(), row.confirmedAt(), row.treatedAt(),
240	                row.releaseAppliedAt(), row.disinfectConfirmedAt(), row.storageConfirmedAt(), row.releasedAt());
241	    }
