273	    /**
274	     * 相邻组团评估：以邻接关系求连通组团，统计组团内 90 日窗口的既有虫情数，
275	     * 恰为第 2 次（既存 1 次）时生成整体预防性消杀评估；第 3 次起不再重复触发。
276	     */
277	    private void triggerEvaluationIfSecond(Zone zone, long newCaseId, LocalDateTime now) {
278	        List<Zone> all = jdbc.sql("SELECT id, code, name, adjacent_codes FROM archive_zone")
279	                .query(ZONE_MAPPER).list();
280	        Map<String, List<String>> adjacency = new LinkedHashMap<>();
281	        for (Zone z : all) {
282	            adjacency.put(z.code(), z.adjacentCodes());
283	        }
284	        Set<String> cluster = new LinkedHashSet<>();
285	        Deque<String> queue = new ArrayDeque<>();
286	        queue.add(zone.code());
287	        while (!queue.isEmpty()) {
288	            String code = queue.poll();
289	            if (cluster.add(code)) {
290	                queue.addAll(adjacency.getOrDefault(code, List.of()));
291	            }
292	        }
293	        List<String> sorted = cluster.stream().sorted().toList();
294	        String placeholders = String.join(", ", Collections.nCopies(sorted.size(), "?"));
295	        JdbcClient.StatementSpec spec = jdbc.sql(
296	                "SELECT COUNT(*) FROM pest_case c JOIN archive_zone z ON c.zone_id = z.id"
297	                        + " WHERE z.code IN (" + placeholders + ") AND c.reported_at >= ? AND c.id <> ?");
298	        for (String code : sorted) {
299	            spec = spec.param(code);
300	        }
301	        long prior = spec.param(now.minusDays(ADJACENT_WINDOW_DAYS)).param(newCaseId)
302	                .query(Long.class).single();
303	        if (prior == 1) {
304	            jdbc.sql("INSERT INTO preventive_evaluation (zone_codes, trigger_case_id, reason, created_at)"
305	                            + " VALUES (?, ?, ?, ?)")
306	                    .param(String.join(",", sorted))
307	                    .param(newCaseId)
308	                    .param("相邻库区 90 日内连续第 2 次虫情，触发整体预防性消杀评估")
309	                    .param(now)
310	                    .update();
311	        }
312	    }
313	
314	    private static List<String> splitAdjacent(String adjacentCodes) {
315	        if (adjacentCodes == null || adjacentCodes.isBlank()) {
316	            return List.of();
317	        }
318	        return List.of(adjacentCodes.split(","));
319	    }
