2	
3	import static org.junit.jupiter.api.Assertions.assertEquals;
4	import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
5	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
6	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
7	
8	import java.util.ArrayList;
9	import java.util.HashSet;
10	import java.util.List;
11	import java.util.Map;
12	import java.util.Set;
13	import java.util.concurrent.CountDownLatch;
14	import java.util.concurrent.ExecutorService;
15	import java.util.concurrent.Executors;
16	import java.util.concurrent.Future;
17	import java.util.concurrent.TimeUnit;
18	import org.junit.jupiter.api.Test;
19	import org.springframework.http.MediaType;
20	import org.springframework.test.web.servlet.MvcResult;
21	
22	/**
23	 * 幂等与并发：同键同参返回首次结果、同键异参 409、
24	 * 并发同键仅生效一次、并发同库区仅一条进行中处置链。
25	 */
26	class IdempotencyConcurrencyTest extends BaseIntegrationTest {
27	
28	    @Test
29	    void sameKeySameParamsReturnsFirstResult() throws Exception {
30	        Map<String, Object> body = Map.of("requestId", "rpt-idem", "reporter", "张三",
31	                "description", "发现虫迹");
32	        long first = reportCase("A", "rpt-idem");
33	
34	        // 同键同参重放：返回首次结果，不产生新记录
35	        postJson("/api/zones/A/pest-reports", body)
36	                .andExpect(status().isOk())
37	                .andExpect(jsonPath("$.caseId").value(first));
38	        assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM pest_case", Long.class));
39	    }
40	
41	    @Test
42	    void sameKeyDifferentParamsRejected() throws Exception {
43	        reportCase("A", "rpt-idem");
44	
45	        // 同键异参：409
46	        postJson("/api/zones/A/pest-reports",
47	                Map.of("requestId", "rpt-idem", "reporter", "李四", "description", "另一处虫迹"))
48	                .andExpect(status().isConflict());
49	        assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM pest_case", Long.class));
50	    }
51	
52	    @Test
53	    void concurrentSameKeySameParamsTakeEffectOnce() throws Exception {
54	        int threads = 8;
55	        Map<String, Object> body = Map.of("requestId", "rpt-conc", "reporter", "张三",
56	                "description", "发现虫迹");
57	        List<Future<MvcResult>> futures = submitConcurrently(threads, i -> body);
58	
59	        Set<Long> caseIds = new HashSet<>();
60	        for (Future<MvcResult> future : futures) {
61	            MvcResult result = future.get(30, TimeUnit.SECONDS);
62	            assertEquals(200, result.getResponse().getStatus());
63	            caseIds.add(objectMapper.readTree(result.getResponse().getContentAsString())
64	                    .get("caseId").asLong());
65	        }
66	        assertEquals(1, caseIds.size());
67	        assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM pest_case", Long.class));
68	        assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM idempotency_record", Long.class));
69	    }
70	
71	    @Test
72	    void concurrentReportsSameZoneAllowSingleActiveChain() throws Exception {
73	        int threads = 8;
74	        List<Future<MvcResult>> futures = submitConcurrently(threads,
75	                i -> Map.of("requestId", "rpt-zone-" + i, "reporter", "张三",
76	                        "description", "发现虫迹"));
77	
78	        int ok = 0;
79	        int conflict = 0;
80	        for (Future<MvcResult> future : futures) {
81	            int responseStatus = future.get(30, TimeUnit.SECONDS).getResponse().getStatus();
82	            if (responseStatus == 200) {
83	                ok++;
84	            } else if (responseStatus == 409) {
85	                conflict++;
86	            }
87	        }
88	        assertEquals(1, ok);
89	        assertEquals(threads - 1, conflict);
90	        assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM pest_case", Long.class));
91	        assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM zone_active_case", Long.class));
92	    }
93	
94	    /**
95	     * 协调真实并发：全部线程就绪后同时放行，设置超时避免悬挂。
96	     */
97	    private List<Future<MvcResult>> submitConcurrently(int threads,
98	            java.util.function.IntFunction<Map<String, Object>> bodyFactory) throws Exception {
99	        ExecutorService pool = Executors.newFixedThreadPool(threads);
100	        CountDownLatch ready = new CountDownLatch(threads);
101	        CountDownLatch start = new CountDownLatch(1);
102	        List<Future<MvcResult>> futures = new ArrayList<>();
103	        for (int i = 0; i < threads; i++) {
104	            final int index = i;
105	            futures.add(pool.submit(() -> {
106	                ready.countDown();
107	                start.await(10, TimeUnit.SECONDS);
108	                return mockMvc.perform(post("/api/zones/A/pest-reports")
109	                        .contentType(MediaType.APPLICATION_JSON)
110	                        .content(objectMapper.writeValueAsString(bodyFactory.apply(index))))
111	                        .andReturn();
112	            }));
113	        }
