            @Valid @RequestBody PestDtos.ReportRequest request) {
        return service.report(zoneCode, request);
    }

    /**
     * 确认虫情（库区进入处置状态）：POST /api/cases/{caseId}/confirm
     */
    @PostMapping("/cases/{caseId}/confirm")
